{"file_path":"src/lcs.js","content":"/**
 * Longest common subsequence over whole lines, compared as exact strings.
 *
 * The traversal prefers the matches that come earliest: walking both documents
 * from the start, a match is taken whenever the two current lines are equal,
 * and otherwise the side whose remaining subsequence is at least as long as the
 * other's advances, with the first document (the base) advancing on a tie.
 */

/**
 * @param {string[]} a first document (the base)
 * @param {string[]} b second document (one side)
 * @returns {Array<[number, number]>} matched index pairs, in order
 */
export function lcsMatches(a, b) {
  const n = a.length
  const m = b.length
  const width = m + 1
  // suffix[i * width + j] = length of the LCS of a[i..] and b[j..]
  const suffix = new Int32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i -= 1) {
    for (let j = m - 1; j >= 0; j -= 1) {
      if (a[i] === b[j]) {
        suffix[i * width + j] = suffix[(i + 1) * width + j + 1] + 1
      } else {
        const dropA = suffix[(i + 1) * width + j]
        const dropB = suffix[i * width + j + 1]
        suffix[i * width + j] = dropA >= dropB ? dropA : dropB
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      matches.push([i, j])
      i += 1
      j += 1
    } else if (suffix[(i + 1) * width + j] >= suffix[i * width + j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return matches
}

/**
 * @typedef {object} Change
 * @property {number} baseStart first base line the change replaces
 * @property {number} baseEnd one past the last base line the change replaces
 * @property {number} sideStart first side line the change inserts
 * @property {number} sideEnd one past the last side line the change inserts
 */

/**
 * Every stretch the common subsequence does not cover, as a run of base lines
 * replaced by a run of the side's lines.
 *
 * @param {string[]} base
 * @param {string[]} side
 * @returns {Change[]}
 */
export function changes(base, side) {
  const matches = lcsMatches(base, side)
  const result = []
  let baseAt = 0
  let sideAt = 0
  const stops = [...matches, [base.length, side.length]]
  for (const [i, j] of stops) {
    if (i > baseAt || j > sideAt) {
      result.push({ baseStart: baseAt, baseEnd: i, sideStart: sideAt, sideEnd: j })
    }
    baseAt = i + 1
    sideAt = j + 1
  }
  return result
}
"}

