{"file_path":"src/diff3.js","content":"/**
 * The three-way merge itself: the changes of both sides against the base are
 * gathered into regions, and each region resolves to one side's lines or to a
 * conflict.
 */

import { changes } from './lcs.js'

/**
 * @typedef {object} Region
 * @property {'stable'|'mine'|'theirs'|'both'|'conflict'} kind
 * @property {string[]} lines the lines the region resolves to (empty on a conflict)
 * @property {string[]} mine
 * @property {string[]} base
 * @property {string[]} theirs
 */

/**
 * The lines one side holds for the base range [lo, hi), given that side's
 * changes inside the range.
 *
 * @param {string[]} base
 * @param {string[]} side
 * @param {import('./lcs.js').Change[]} own
 * @param {number} lo
 * @param {number} hi
 * @returns {string[]}
 */
function sideLines(base, side, own, lo, hi) {
  if (own.length === 0) return base.slice(lo, hi)
  let first = own[0]
  let last = own[0]
  for (const change of own) {
    if (change.baseStart < first.baseStart) first = change
    if (change.baseEnd > last.baseEnd) last = change
  }
  const start = first.sideStart - (first.baseStart - lo)
  const end = last.sideEnd + (hi - last.baseEnd)
  return side.slice(start, end)
}

/**
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 * @returns {Region[]}
 */
export function merge(mine, base, theirs) {
  const all = [
    ...changes(base, mine).map(change => ({ ...change, side: 'mine' })),
    ...changes(base, theirs).map(change => ({ ...change, side: 'theirs' })),
  ]
  // Ordered by where they start in the base, mine before theirs on a tie; the
  // sort is stable, so each side keeps its own order.
  all.sort((left, right) => left.baseStart - right.baseStart)

  const regions = []
  let stableAt = 0
  let at = 0
  while (at < all.length) {
    const lo = all[at].baseStart
    let hi = all[at].baseEnd
    const group = [all[at]]
    at += 1
    while (at < all.length && all[at].baseStart <= hi) {
      if (all[at].baseEnd > hi) hi = all[at].baseEnd
      group.push(all[at])
      at += 1
    }

    if (lo > stableAt) {
      const lines = base.slice(stableAt, lo)
      regions.push({ kind: 'stable', lines, mine: lines, base: lines, theirs: lines })
    }
    stableAt = hi

    const baseLines = base.slice(lo, hi)
    const mineLines = sideLines(base, mine, group.filter(c => c.side === 'mine'), lo, hi)
    const theirLines = sideLines(base, theirs, group.filter(c => c.side === 'theirs'), lo, hi)
    let kind
    let lines
    if (same(mineLines, theirLines)) {
      kind = 'both'
      lines = mineLines
    } else if (same(mineLines, baseLines)) {
      kind = 'theirs'
      lines = theirLines
    } else if (same(theirLines, baseLines)) {
      kind = 'mine'
      lines = mineLines
    } else {
      kind = 'conflict'
      lines = []
    }
    regions.push({ kind, lines, mine: mineLines, base: baseLines, theirs: theirLines })
  }

  if (base.length > stableAt) {
    const lines = base.slice(stableAt)
    regions.push({ kind: 'stable', lines, mine: lines, base: lines, theirs: lines })
  }
  return regions
}

/**
 * @param {string[]} left
 * @param {string[]} right
 * @returns {boolean}
 */
function same(left, right) {
  return left.length === right.length && left.every((line, index) => line === right[index])
}
"}

